Here's an expense tracker for this month. Add an item, set a budget, and the totals update as you go. It lives only in this page, so it clears when you close it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#fafafa;color:#222}
h1{font-size:18px;margin:0 0 12px}
.row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}
input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
button{background:#2b6cb0;color:#fff;border-color:#2b6cb0;cursor:pointer}
button.x{background:none;color:#c53030;border:none;padding:2px 6px}
.card{background:#fff;border:1px solid #e2e2e2;border-radius:10px;padding:12px;margin-bottom:12px}
.big{font-size:24px;font-weight:600}
.bar{height:8px;background:#e2e8f0;border-radius:4px;overflow:hidden;margin:3px 0 8px}
.bar i{display:block;height:100%;background:#2b6cb0}
.item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.sub{color:#666;font-size:12px}
.over{color:#c53030}
</style></head><body>
<h1>Monthly expenses</h1>

<div class="card">
  <div class="row">
    <label>Monthly budget (₹) <input id="budget" type="number" min="0" value="50000"></label>
  </div>
  <div class="sub">Spent so far</div>
  <div class="big" id="total">₹0</div>
  <div id="left" class="sub"></div>
  <div class="bar"><i id="budgetBar" style="width:0%"></i></div>
</div>

<div class="card">
  <div class="row">
    <input id="desc" placeholder="What did you spend on?" style="flex:2;min-width:140px">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)" style="flex:1;min-width:100px">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <button id="add">Add</button>
  </div>
</div>

<div class="card"><b>By category</b><div id="cats" style="margin-top:8px"></div></div>
<div class="card"><b>All items</b><div id="list" style="margin-top:6px"></div></div>

<script>
var items=[];
var $=function(id){return document.getElementById(id)};
function inr(n){return "₹"+Math.round(n).toLocaleString("en-IN")}
function render(){
  var total=0,by={};
  items.forEach(function(e){total+=e.amt;by[e.cat]=(by[e.cat]||0)+e.amt});
  $("total").textContent=inr(total);
  var b=parseFloat($("budget").value)||0;
  var left=b-total;
  $("left").textContent=b?(left>=0?inr(left)+" left of "+inr(b):inr(-left)+" over budget"):"Set a budget to track what's left";
  $("left").className="sub"+(left<0&&b?" over":"");
  $("budgetBar").style.width=(b?Math.min(100,total/b*100):0)+"%";
  var c=$("cats");c.textContent="";
  Object.keys(by).sort(function(a,b){return by[b]-by[a]}).forEach(function(k){
    var d=document.createElement("div");
    var t=document.createElement("div");t.style.display="flex";t.style.justifyContent="space-between";
    var a=document.createElement("span");a.textContent=k;
    var v=document.createElement("span");v.textContent=inr(by[k]);
    t.appendChild(a);t.appendChild(v);
    var bar=document.createElement("div");bar.className="bar";
    var i=document.createElement("i");i.style.width=(total?by[k]/total*100:0)+"%";
    bar.appendChild(i);d.appendChild(t);d.appendChild(bar);c.appendChild(d);
  });
  if(!items.length)c.textContent="Nothing yet.";
  var l=$("list");l.textContent="";
  if(!items.length)l.textContent="Nothing yet.";
  items.forEach(function(e,idx){
    var r=document.createElement("div");r.className="item";
    var left=document.createElement("div");
    var n=document.createElement("div");n.textContent=e.desc;
    var s=document.createElement("div");s.className="sub";s.textContent=e.cat;
    left.appendChild(n);left.appendChild(s);
    var right=document.createElement("div");
    var p=document.createElement("span");p.textContent=inr(e.amt);
    var x=document.createElement("button");x.className="x";x.textContent="✕";
    x.onclick=function(){items.splice(idx,1);render()};
    right.appendChild(p);right.appendChild(x);
    r.appendChild(left);r.appendChild(right);l.appendChild(r);
  });
}
function add(){
  var amt=parseFloat($("amt").value);
  if(!(amt>0))return;
  items.unshift({desc:$("desc").value.trim()||"Expense",amt:amt,cat:$("cat").value});
  $("desc").value="";$("amt").value="";$("desc").focus();render();
}
$("add").onclick=add;
$("amt").onkeydown=function(e){if(e.key==="Enter")add()};
$("budget").oninput=render;
render();
</script>
</body></html>
```

